/**
 * The platform's own columns on Better Auth's `user` model.
 *
 * Declared as a plugin because `packages/nest/schema/src/global/identity/auth.ts` is GENERATED by
 * `better-auth generate`: a plugin's `schema` is an input to that generation, so the columns survive a regen.
 *
 * No explicit return type: the client plugin links to this type via `$InferServerPlugin`, and an annotation that widens
 * the literal would erase the fields from the client session.
 */
export const deployerUserSchemaPlugin = () => ({
	id: "deployer-user-schema" as const,
	schema: {
		user: {
			// `as const` is load-bearing: without it `required: false` / `input: false` widen to `boolean`, and Better
			// Auth's `InferFieldsInputClient` then reads every field as writable, making a nullable column a REQUIRED
			// field of `signUp.email`'s input type.
			fields: {
				role: { type: "string", required: true, defaultValue: "user", input: false },
				banned: { type: "boolean", required: false, defaultValue: false, input: false },
				banReason: { type: "string", required: false, input: false, defaultValue: null },
				banExpires: { type: "date", required: false, input: false, defaultValue: null },
				/** The admin a request is impersonating on behalf of; empty for a normal session. */
				impersonatedBy: { type: "string", required: false, input: false, defaultValue: null },
			} as const,
		},
	},
});
